# desligamento-notebook.tf -- verificacao periodica de ociosidade + horario

resource "aws_scheduler_schedule" "checar_ociosidade_notebook" {
  name       = "${var.projeto}-checar-ociosidade-notebook"
  group_name = "default"

  flexible_time_window { mode = "OFF" }
  schedule_expression = "rate(15 minutes)"

  target {
    arn      = aws_lambda_function.parar_notebook_ocioso.arn
    role_arn = aws_iam_role.scheduler_invoca_lambda.arn
  }
}

resource "aws_lambda_function" "parar_notebook_ocioso" {
  function_name = "${var.projeto}-parar-notebook-ocioso"
  runtime       = "python3.12"
  handler       = "parar_notebook.handler"
  timeout       = 30
  role          = aws_iam_role.lambda_notebook.arn
  filename      = data.archive_file.parar_notebook.output_path

  environment {
    variables = {
      # Janela em que o notebook NAO pode ser parado, mesmo ocioso -- horario
      # comercial declarado, nao deduzido.
      HORARIO_INICIO   = "08:00"
      HORARIO_FIM      = "19:00"
      LIMIAR_OCIOSO_MIN = "30"
    }
  }

  tags = { Projeto = var.projeto, Time = "dados" }
}

# ciclo-de-vida-experimentos.tf -- expira o que nao foi promovido, preserva
# o que foi

resource "aws_s3_bucket_lifecycle_configuration" "experimentos" {
  bucket = aws_s3_bucket.experimentos.id

  rule {
    id     = "expirar-nao-promovido"
    status = "Enabled"

    filter {
      tag {
        key   = "Promovido"
        value = "false"
      }
    }

    # 30 dias em Standard-IA reduz custo de armazenamento sem apagar nada;
    # so aos 90 dias sem promocao o objeto e removido de fato.
    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    expiration {
      days = 90
    }
  }

  rule {
    # Artefato com a tag Promovido=true nunca cai nesta regra -- sem filtro
    # de tag correspondente, o S3 nao aplica expiracao a ele.
    id     = "preservar-promovido"
    status = "Enabled"

    filter {
      tag {
        key   = "Promovido"
        value = "true"
      }
    }

    transition {
      days          = 90
      storage_class = "STANDARD_IA"
    }
  }
}

# endpoint-recomendacao-serverless.tf

resource "aws_sagemaker_model" "recomendacao_cpu" {
  name               = "${var.projeto}-recomendacao-cpu"
  execution_role_arn = aws_iam_role.sagemaker_execucao.arn

  primary_container {
    # Mesma logica de inferencia do endpoint de tempo real -- versao
    # compilada sem dependencia de CUDA, empacotada separadamente.
    image = "${var.conta_ecr}.dkr.ecr.${var.regiao}.amazonaws.com/recomendacao-cpu:latest"
    model_data_url = "s3://cadencia-ml-experimentos/producao/recomendacao-v14-cpu.tar.gz"
  }
}

resource "aws_sagemaker_endpoint_configuration" "recomendacao_serverless" {
  name = "${var.projeto}-recomendacao-serverless"

  production_variants {
    variant_name = "principal"
    model_name   = aws_sagemaker_model.recomendacao_cpu.name

    serverless_config {
      memory_size_in_mb = 3072
      max_concurrency   = 10
    }
  }

  tags = { Projeto = var.projeto, Time = "dados", Modo = "serverless" }
}

resource "aws_sagemaker_endpoint" "recomendacao" {
  name                 = "${var.projeto}-recomendacao"
  endpoint_config_name = aws_sagemaker_endpoint_configuration.recomendacao_serverless.name
}

// ClienteRecomendacao.cs -- chamada sincrona ao endpoint serverless. O
// consumidor (pagina de produto) tolera alguns segundos de cold start
// ocasional -- diferente do painel de atendimento do L74/L79.

using Amazon.SageMakerRuntime;
using Amazon.SageMakerRuntime.Model;

namespace Cadencia.Recomendacao;

public class ClienteRecomendacao
{
    private readonly AmazonSageMakerRuntimeClient _cliente = new(new AmazonSageMakerRuntimeConfig
    {
        Timeout = TimeSpan.FromSeconds(4), // orcamento maior que o do painel de atendimento
    });

    public async Task<IReadOnlyList<string>> RecomendarAsync(string payloadJson)
    {
        var resposta = await _cliente.InvokeEndpointAsync(new InvokeEndpointRequest
        {
            EndpointName = "cadencia-recomendacao",
            ContentType  = "application/json",
            Body         = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(payloadJson)),
        });

        using var leitor = new StreamReader(resposta.Body);
        var corpo = await leitor.ReadToEndAsync();
        return System.Text.Json.JsonDocument.Parse(corpo)
            .RootElement.GetProperty("produtos_recomendados")
            .EnumerateArray().Select(x => x.GetString()!).ToList();
    }
}
